Map<String, dynamic> _f(String id, String name, String serving, double cal,
    double carbs, double protein, double fat, double fiber, double sugar,
    double sodium, double chol, List<Map<String, dynamic>> vitamins, String tip) {
  return {
    'id': id,
    'food_name': name,
    'serving_size': serving,
    'calories': cal,
    'carbs': {'name': 'Carbohydrates', 'amount': carbs, 'unit': 'g', 'daily_percent': (carbs / 300 * 100).round()},
    'protein': {'name': 'Protein', 'amount': protein, 'unit': 'g', 'daily_percent': (protein / 50 * 100).round()},
    'fat': {'name': 'Fat', 'amount': fat, 'unit': 'g', 'daily_percent': (fat / 65 * 100).round()},
    'fiber': {'name': 'Fiber', 'amount': fiber, 'unit': 'g', 'daily_percent': (fiber / 25 * 100).round()},
    'sugar': {'name': 'Sugar', 'amount': sugar, 'unit': 'g', 'daily_percent': (sugar / 50 * 100).round()},
    'sodium': {'name': 'Sodium', 'amount': sodium, 'unit': 'mg', 'daily_percent': (sodium / 2300 * 100).round()},
    'cholesterol': {'name': 'Cholesterol', 'amount': chol, 'unit': 'mg', 'daily_percent': (chol / 300 * 100).round()},
    'vitamins': vitamins,
    'health_tip': tip,
  };
}

Map<String, dynamic> _v(String name, double amount) {
  return {'name': name, 'amount': amount, 'unit': '%DV'};
}
